package com.dexm.personajes.adapter.out.persistence;
import jakarta.persistence.*;
@Entity @Table(name="character_minor_attribute_values", uniqueConstraints=@UniqueConstraint(columnNames={"character_id","definition_id"}))
public class CharacterMinorAttributeValueEntity { @Id private String id; private String characterId; private String definitionId; @Column(name="attribute_value") private int value; protected CharacterMinorAttributeValueEntity(){} public CharacterMinorAttributeValueEntity(String id,String characterId,String definitionId,int value){this.id=id;this.characterId=characterId;this.definitionId=definitionId;this.value=value;} public String getId(){return id;} public String getCharacterId(){return characterId;} public String getDefinitionId(){return definitionId;} public int getValue(){return value;} public void setValue(int v){value=v;} }
